      double startAngle, double angle, double radius, String color) {
    double startRad = startAngle * (3.14159 / 180);
    double endRad = (startAngle + angle) * (3.14159 / 180);
    double x1 = 103.455 + radius * cos(startRad);
    double y1 = 103.884 + radius * sin(startRad);
    double x2 = 103.455 + radius * cos(endRad);
    double y2 = 103.884 + radius * sin(endRad);
    return '''
<path d="M103.455 103.884 L$x1 $y1 A$radius $radius 0 ${angle > 180 ? 1 : 0} 1 $x2 $y2 Z" fill="$color" stroke="#F2F2F7" stroke-width="0.86" />
''';
  }

  @override
  Widget build(BuildContext context) {
    final int redCount = widget.equipmentCounts['redTags'] ?? 0;
    final int yellowCount = widget.equipmentCounts['yellowTags'] ?? 0;
    final int greenCount = widget.equipmentCounts['greenTags'] ?? 0;
    final int totalCount = redCount + yellowCount + greenCount;
    final int redPercentage =
        totalCount > 0 ? (redCount * 100 ~/ totalCount) : 0;
    final int yellowPercentage =
        totalCount > 0 ? (yellowCount * 100 ~/ totalCount) : 0;
    final int greenPercentage =
        totalCount > 0 ? (greenCount * 100 ~/ totalCount) : 0;
    updateSvgString(redPercentage, yellowPercentage, greenPercentage);
    return LayoutBuilder(builder: (context, orientation) {
      final double screenWidth = MediaQuery.of(context).size.width;
      final double screenHeight = MediaQuery.of(context).size.height;
      return Padding(
        padding: const EdgeInsets.only(top: 5.0),
        child: Column(
          children: [
            Column(
              children: [
                !widget.statusZero
                    ? Stack(
                        children: [
                          SvgPicture.string(
                            svgString,
                            width: screenWidth * 0.3,
                            height: screenHeight * 0.3,
                          ),
                          Positioned(
                            left: 15,
                            top: 20,
                            child: SvgPicture.string(
                              redLine,
                              width: 58,
                              height: 45,
                            ),
                          ),
                          Positioned(
                            left: 0,
                            top: 10,
                            child: Column(
                              children: [
                                SvgPicture.asset(
                                  'lib/src/features/dashboard/assets/svg/card_red_flag.svg',
                                  width: screenWidth * 0.025,
                                  height: screenHeight * 0.033,
                                ),
                                Text("$redPercentage%",
                                    style: TextStyle(
                                        fontSize: screenHeight * 0.015,
                                        fontWeight: FontWeight.w600))
                              ],
                            ),
                          ),
                          Positioned(
                            right: 15,
                            top: 20,
                            child: SvgPicture.string(
                              greenLine,
                              width: 58,
                              height: 45,
                            ),
                          ),
                          Positioned(
                            right: 0,
                            top: 10,
                            child: Column(
                              children: [
                                SvgPicture.asset(
                                  'lib/src/features/dashboard/assets/svg/card_green_flag.svg',
                                  width: screenWidth * 0.025,
                                  height: screenHeight * 0.033,
                                ),
                                Text("$greenPercentage%",
                                    style: TextStyle(
                                        fontSize: screenHeight * 0.015,
                                        fontWeight: FontWeight.w600))
                              ],
                            ),
                          ),
                          Positioned(
                            left: 20,
                            bottom: 15,
                            child: SvgPicture.string(
                              yellowLine,
                              width: 58,
                              height: 45,
                            ),
                          ),
                          Positioned(
                            left: 0,
                            bottom: 5,
                            child: Column(
                              children: [
                                Text("$yellowPercentage%",
                                    style: TextStyle(
                                        fontSize: screenHeight * 0.015,
                                        fontWeight: FontWeight.w600)),
                                SvgPicture.asset(
                                  'lib/src/features/dashboard/assets/svg/card_yellow_flag.svg',
                                  width: screenWidth * 0.025,
                                  height: screenHeight * 0.033,
                                ),
                              ],
                            ),
                          ),
                        ],
                      )
                    : SizedBox(
                        width: screenWidth * 0.3,
                        height: screenHeight * 0.3,
                        child: const Center(
                          child: Text("No Record Found"),
                        )),
              ],
            ),
            SizedBox(
              height: screenHeight * 0.029,
            ),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceEvenly,
              children: [
                ToggleWidget(
                    screenWidth: screenWidth,
                    screenHeight: screenHeight,
                    number: redCount,
                    svgFlag:
                        'lib/src/features/dashboard/assets/svg/red_flag.svg',
                    label: 'Red Tags'),
                SizedBox(
                  width: screenWidth * 0.020,
                ),
                ToggleWidget(
                    screenWidth: screenWidth,
                    screenHeight: screenHeight,
                    number: yellowCount,
                    svgFlag:
                        'lib/src/features/dashboard/assets/svg/yellow_flag.svg',
                    label: 'Yellow Tags'),
                SizedBox(
